//! `cargo xtask cli-gen`: regenerates the tool list linked into the `kortex` CLI
//! (`crates/kortex-cli/Cargo.toml` dependency block and `src/generated.rs`).
use std::fmt::Write as _;
use std::fs;

use crate::tools;

const BEGIN: &str = "# --- generated by `cargo xtask cli-gen` (do not edit) ---";
const END: &str = "# --- end generated ---";

/// Returns `(Cargo.toml, generated.rs)` contents for the current set of tools.
pub fn build() -> Result<(String, String), String> {
    let mut deps = String::new();
    let mut code = String::from(
        "// GENERATED by `cargo xtask cli-gen` — do not edit.\nuse crate::{RunFut, ToolEntry};\nuse kortex_runtime::{Cx, ValueMap};\n\n",
    );
    let mut table = String::from("pub static TOOLS: &[ToolEntry] = &[\n");
    let mut found = tools::discover()?;
    found.sort_by(|a, b| a.dir.cmp(&b.dir));
    for (i, t) in found.iter().enumerate() {
        let c = t
            .contract
            .as_ref()
            .map_err(|e| format!("{} : {e}", t.dir.display()))?;
        let (universe, name) = c.tool.id.split_once('.').ok_or("id invalide")?;
        let pkg = format!("tool-{universe}-{name}");
        let lib = pkg.replace('-', "_");
        let _ = writeln!(
            deps,
            "{pkg} = {{ path = \"../../{}\" }}",
            crate::fwd(&t.dir)
        );
        let _ = writeln!(
            code,
            "fn run_{i}<'a>(i: &'a ValueMap, p: &'a ValueMap, cx: &'a mut Cx) -> RunFut<'a> {{\n    Box::pin({lib}::run_map(i, p, cx))\n}}\n"
        );
        let _ = writeln!(
            table,
            "    ToolEntry {{ id: {:?}, contract: {lib}::CONTRACT, run: run_{i} }},",
            c.tool.id
        );
    }
    table.push_str("];\n");
    code.push_str(&table);

    let manifest = fs::read_to_string("crates/kortex-cli/Cargo.toml")
        .map_err(|e| format!("kortex-cli/Cargo.toml : {e}"))?;
    let (head, rest) = manifest
        .split_once(BEGIN)
        .ok_or("marqueur BEGIN absent de crates/kortex-cli/Cargo.toml")?;
    let (_, tail) = rest.split_once(END).ok_or("marqueur END absent")?;
    Ok((format!("{head}{BEGIN}\n{deps}{END}{tail}"), code))
}

pub fn run() -> Result<(), String> {
    let (manifest, code) = build()?;
    fs::write("crates/kortex-cli/Cargo.toml", manifest).map_err(|e| e.to_string())?;
    fs::write("crates/kortex-cli/src/generated.rs", code).map_err(|e| e.to_string())?;
    println!("✓ crates/kortex-cli régénéré");
    Ok(())
}
